{
  "incident_id": "INC-036",
  "root_cause_category": "expired_tls_cert",
  "root_cause_summary": "The TLS certificate for the inventory service expired, leading to SSL handshake failures and 5xx errors.",
  "confidence": "high",
  "claims": [
    {
      "statement": "The inventory service error rate peaked at 41.18% around the time of the alert.",
      "evidence_ids": [
        "M-023"
      ]
    },
    {
      "statement": "Logs show multiple SSL handshake failed and certificate expired errors indicating that the inventory internal certificate expired at 2026-08-15T15:39:00Z.",
      "evidence_ids": [
        "L-0289",
        "L-0292"
      ]
    }
  ],
  "recommended_actions": [
    {
      "statement": "Issue and install a renewed certificate, then reload or restart the service so it picks the new one up.",
      "evidence_ids": [
        "R-07-5"
      ]
    },
    {
      "statement": "Fix whatever blocked automated renewal and run the renewal by hand.",
      "evidence_ids": [
        "R-07-5"
      ]
    },
    {
      "statement": "Check other certificates issued around the same day for the same fault.",
      "evidence_ids": [
        "R-07-5"
      ]
    }
  ],
  "ruled_out": [
    "bad_deployment",
    "db_connection_pool_exhaustion",
    - "slow_query_missing_index",
    - "downstream_timeout",
    - "memory_leak_oom",
    - "disk_full",
    - "misconfiguration",
    - "traffic_spike_rate_limit",
    - "cache_stampede_outage"
  ]
}

